        },
        logs: data.recent_logs
      };
      fs.writeFileSync(STATE_FILE, JSON.stringify(state, null, 2));
      broadcastState(state);
    } catch (e) {}
  });
}

const intervalTimer = setInterval(runRealBenchmarkStep, 3500);
runRealBenchmarkStep();

